import type { ReactElement } from "react";

export type FormErrorSource = "client" | "server";

export interface FormErrorSummaryItem {
  readonly fieldId: string;
  readonly controlId: string;
  readonly label: string;
  readonly message: string;
  readonly code: string;
  readonly order: number;
  readonly source: FormErrorSource;
}

export interface FormServerError {
  readonly code: string;
  readonly message: string;
  readonly retryable: boolean;
}

export type FormErrorControlFocusReason = "single-invalid" | "summary-link";

export interface FormErrorControlFocusRequest {
  readonly controlId: string;
  readonly fieldId: string;
  readonly reason: FormErrorControlFocusReason;
  readonly submissionAttempt: number;
}

export type FormErrorFocusControl = (
  request: FormErrorControlFocusRequest,
) => boolean;

export type FormErrorFocusEvent =
  | {
      readonly target: "summary";
      readonly reason: "multiple-invalid" | "server-error" | "control-fallback";
      readonly summaryId: string;
      readonly submissionAttempt: number;
    }
  | {
      readonly target: "control";
      readonly reason: FormErrorControlFocusReason;
      readonly controlId: string;
      readonly fieldId: string;
      readonly submissionAttempt: number;
    };

