import type { ReactElement, ReactNode } from "react";
import type {
  FormErrorFocusControl,
  FormErrorSummaryItem,
  FormServerError,
} from "@/components/ui/form-error-summary";

export type EntityWizardPanel =
  | { readonly kind: "step"; readonly stepId: string }
  | { readonly kind: "review" };

export type EntityWizardStatus =
  | "idle"
  | "validating-step"
  | "submitting"
  | "submit-error"
  | "success";

export interface EntityWizardStep {
  readonly id: string;
  readonly label: string;
  readonly heading: string;
  readonly description?: string;
  readonly firstFieldControlId: string;
  readonly reviewLabel: string;
}

export type EntityWizardStepValidationResult =
  | { readonly status: "valid" }
  | { readonly status: "invalid"; readonly errors: readonly FormErrorSummaryItem[] };

export type EntityWizardSubmitResult<TEntityId extends string = string> =
  | {
      readonly status: "success";
      readonly entityId: TEntityId;
      readonly destinationHref: string;
      readonly focusTargetId: string;
    }
  | {
      readonly status: "validation-error";
      readonly errors: readonly FormErrorSummaryItem[];
    }
  | { readonly status: "server-error"; readonly error: FormServerError }
  | { readonly status: "stale"; readonly error: FormServerError };

export type EntityWizardCloseReason =
  | "cancel-button"
  | "escape-key"
  | "overlay-dismiss"
  | "dirty-discard-confirmed"
  | "success";

export interface EntityWizardOpenChangeEvent {
  readonly reason: "trigger" | EntityWizardCloseReason;
  readonly dirty: boolean;
}

export interface EntityWizardPanelChangeEvent {
  readonly reason: "back" | "next" | "edit";
  readonly from: EntityWizardPanel;
  readonly to: EntityWizardPanel;
}

export interface EntityWizardStepValidationEvent {
  readonly stepId: string;
  readonly result: EntityWizardStepValidationResult;
}

export type EntityWizardFocusRequest =
  | { readonly target: "title"; readonly wizardId: string }
  | { readonly target: "step-heading"; readonly wizardId: string; readonly stepId: string }
  | { readonly target: "field"; readonly wizardId: string; readonly controlId: string }
  | { readonly target: "review-heading"; readonly wizardId: string }
  | { readonly target: "opener"; readonly wizardId: string }
  | { readonly target: "success-destination"; readonly wizardId: string; readonly focusTargetId: string };

export interface EntityWizardRenderStepContext {
  readonly step: EntityWizardStep;
  readonly status: EntityWizardStatus;
  readonly disabled: boolean;
  readonly errors: readonly FormErrorSummaryItem[];
}

export interface EntityWizardRenderReviewContext {
  readonly steps: readonly EntityWizardStep[];
  readonly status: EntityWizardStatus;
  readonly onEdit: (stepId: string) => void;
}

export interface EntityWizardProps<TEntityId extends string = string> {
  readonly id: string;
  readonly title: string;
  readonly description?: string;
  readonly trigger: ReactElement;
  readonly open: boolean;
  readonly panel: EntityWizardPanel;
  readonly dirty: boolean;
  readonly status: EntityWizardStatus;
  readonly steps: readonly EntityWizardStep[];
  readonly errors: readonly FormErrorSummaryItem[];
  readonly serverError?: FormServerError | null;
  readonly submissionAttempt: number;
  readonly renderStep: (context: EntityWizardRenderStepContext) => ReactNode;
  readonly renderReview: (context: EntityWizardRenderReviewContext) => ReactNode;
  readonly validateStep: (stepId: string) => Promise<EntityWizardStepValidationResult>;
  readonly submit: () => Promise<EntityWizardSubmitResult<TEntityId>>;
  readonly focusControl: FormErrorFocusControl;
  readonly onOpenChange: (open: boolean, event: EntityWizardOpenChangeEvent) => void;
  readonly onPanelChange: (panel: EntityWizardPanel, event: EntityWizardPanelChangeEvent) => void;
  readonly onStepValidationResult: (event: EntityWizardStepValidationEvent) => void;
  readonly onSubmitResult: (result: EntityWizardSubmitResult<TEntityId>) => void;
  readonly onFocusRequest?: (request: EntityWizardFocusRequest) => void;
  readonly className?: string;
}

export declare function EntityWizard<TEntityId extends string = string>(
  props: EntityWizardProps<TEntityId>,
): ReactElement;

export interface FormErrorSummaryProps {
  readonly id: string;
  readonly heading?: string;
  readonly errors: readonly FormErrorSummaryItem[];
  readonly serverError?: FormServerError | null;
  readonly submissionAttempt: number;
  readonly focusControl: FormErrorFocusControl;
  readonly onFocusRequest?: (event: FormErrorFocusEvent) => void;
  readonly onRetry?: () => void;
  readonly retryPending?: boolean;
  readonly className?: string;
}

export declare function FormErrorSummary(
  props: FormErrorSummaryProps,
): ReactElement | null;

