  open: true,
  panel: { kind: "step", stepId: "basis" },
  dirty: false,
  status: "idle",
  steps: [
    {
      "id": "basis",
      "label": "Basis",
      "heading": "Basisgegevens",
      "firstFieldControlId": "title",
      "reviewLabel": "Basisgegevens"
    },
    {
      "id": "location",
      "label": "Locatie",
      "heading": "Klant en locatie",
      "firstFieldControlId": "customerId",
      "reviewLabel": "Klant en locatie"
    },
    {
      "id": "planning",
      "label": "Planning",
      "heading": "Planning",
      "firstFieldControlId": "scheduledDate",
      "reviewLabel": "Planning"
    }
  ],
  errors: [],
  serverError: null,
  submissionAttempt: 0,
  renderStep: () => null,
  renderReview: () => null,
  validateStep: async () => ({ status: "valid" }),
  submit: async () => ({
    status: "success",
    entityId: "FG-2048" as AssignmentId,
    destinationHref: "/assignments/FG-2048",
    focusTargetId: "assignment-detail-heading",
  }),
  focusControl: () => true,
  onOpenChange: () => undefined,
  onPanelChange: () => undefined,
  onStepValidationResult: () => undefined,
  onSubmitResult: () => undefined,
} satisfies EntityWizardProps<AssignmentId>;

export const assignmentErrorSummaryContract = {
  id: "assignment-form-errors",
  errors: [],
  serverError: null,
  submissionAttempt: 0,
  focusControl: () => true,
} satisfies FormErrorSummaryProps;

